def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter, defaultdict

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not points:
        return out
    cr = sum(r for r, c in points) / len(points)
    cc = sum(c for r, c in points) / len(points)

    colors = set(grid[r][c] for r, c in points)
    for color in colors:
        for key_fn in (lambda r, c: r - c, lambda r, c: r + c):
            groups = defaultdict(list)
            for r in range(h):
                for c in range(w):
                    if grid[r][c] == color:
                        groups[key_fn(r, c)].append((r, c))

            for group in groups.values():
                group.sort()
                runs = []
                run = []
                for p in group:
                    if run and p[0] != run[-1][0] + 1:
                        runs.append(run)
                        run = []
                    run.append(p)
                if run:
                    runs.append(run)

                for run in runs:
                    if len(run) < 2:
                        continue
                    a, b = run[0], run[-1]
                    da = (a[0] - cr) ** 2 + (a[1] - cc) ** 2
                    db = (b[0] - cr) ** 2 + (b[1] - cc) ** 2
                    end = a if da >= db else b
                    neighbor = run[1] if end == a else run[-2]
                    dr = end[0] - neighbor[0]
                    dc = end[1] - neighbor[1]
                    r, c = end[0] + dr, end[1] + dc
                    while 0 <= r < h and 0 <= c < w:
                        if out[r][c] != bg:
                            break
                        out[r][c] = color
                        r += dr
                        c += dc
    return out
